"""Validation script for upstream pipeline outputs.

Checks existence, non-emptiness, schema correctness, and basic data integrity
for the following files:
  - outputs/t01_selected_indicators.csv
  - outputs/t05_clean_stops.csv
  - outputs/t08_pois_clean.csv
  - outputs/t10_accessibility_scores.csv
  - outputs/t13_city_clusters.csv

Writes results to outputs/t14_validation_summary.json.
"""

import csv
import json
import os
import sys


def read_csv_rows(path):
    """Read a CSV file and return (header, rows) or (None, None) on failure."""
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            header = next(reader, None)
            if header is None:
                return None, []
            rows = list(reader)
            return header, rows
    except FileNotFoundError:
        return None, None
    except Exception:
        return None, None


def validate_file_exists(path, label):
    """Check that a file exists and is non-empty."""
    if not os.path.isfile(path):
        return False, f"{label}: file not found at {path}"
    if os.path.getsize(path) == 0:
        return False, f"{label}: file is empty"
    return True, f"{label}: file exists and is non-empty"


def validate_csv_columns(path, expected_cols, label):
    """Check that a CSV has the expected columns."""
    header, rows = read_csv_rows(path)
    if header is None:
        return False, f"{label}: could not read CSV header"
    actual = [c.strip() for c in header]
    if actual != expected_cols:
        return False, (
            f"{label}: column mismatch. "
            f"expected {expected_cols}, got {actual}"
        )
    return True, f"{label}: columns match ({len(expected_cols)} columns)"


def validate_csv_row_count(path, label, min_rows=1):
    """Check that a CSV has at least min_rows data rows (excluding header)."""
    header, rows = read_csv_rows(path)
    if header is None:
        return False, f"{label}: could not read CSV"
    if len(rows) < min_rows:
        return False, (
            f"{label}: expected at least {min_rows} data rows, "
            f"got {len(rows)}"
        )
    return True, f"{label}: has {len(rows)} data rows (>= {min_rows})"


def validate_no_empty_required_cols(path, col_indices, label):
    """Check that required columns have no empty values in data rows."""
    header, rows = read_csv_rows(path)
    if header is None:
        return False, f"{label}: could not read CSV"
    col_names = [header[i].strip() for i in col_indices]
    for ri, row in enumerate(rows):
        for ci in col_indices:
            if ci >= len(row) or row[ci].strip() == "":
                return False, (
                    f"{label}: empty value in column '{col_names[ci]}' "
                    f"at data row {ri + 1}"
                )
    return True, f"{label}: no empty values in required columns {col_names}"


def validate_numeric_columns(path, col_indices, label):
    """Check that specified columns contain valid numeric values."""
    header, rows = read_csv_rows(path)
    if header is None:
        return False, f"{label}: could not read CSV"
    col_names = [header[i].strip() for i in col_indices]
    for ri, row in enumerate(rows):
        for ci in col_indices:
            val = row[ci].strip() if ci < len(row) else ""
            if val == "":
                continue  # allow missing numeric values
            try:
                float(val)
            except ValueError:
                return False, (
                    f"{label}: non-numeric value '{val}' in column "
                    f"'{col_names[ci]}' at data row {ri + 1}"
                )
    return True, f"{label}: numeric columns {col_names} contain valid numbers"


def validate_value_range(path, col_index, lo, hi, label):
    """Check that a numeric column falls within [lo, hi]."""
    header, rows = read_csv_rows(path)
    if header is None:
        return False, f"{label}: could not read CSV"
    col_name = header[col_index].strip()
    for ri, row in enumerate(rows):
        val = row[col_index].strip() if col_index < len(row) else ""
        if val == "":
            continue
        try:
            fval = float(val)
        except ValueError:
            return False, (
                f"{label}: non-numeric value '{val}' in column "
                f"'{col_name}' at data row {ri + 1}"
            )
        if fval < lo or fval > hi:
            return False, (
                f"{label}: value {fval} in column '{col_name}' at "
                f"data row {ri + 1} is outside range [{lo}, {hi}]"
            )
    return True, (
        f"{label}: column '{col_name}' values are within [{lo}, {hi}]"
    )


def run_validations():
    """Run all validation checks and return the list of results."""
    results = []

    # --- t01_selected_indicators.csv ---
    t01_path = "outputs/t01_selected_indicators.csv"
    t01_expected_cols = [
        "indicator_id", "indicator_name", "theme",
        "justification", "expected_direction",
    ]
    results.append(validate_file_exists(t01_path, "t01_selected_indicators"))
    results.append(validate_csv_columns(t01_path, t01_expected_cols, "t01_selected_indicators"))
    results.append(validate_csv_row_count(t01_path, "t01_selected_indicators", min_rows=1))
    results.append(validate_no_empty_required_cols(
        t01_path, [0, 2, 4], "t01_selected_indicators"
    ))

    # --- t05_clean_stops.csv ---
    t05_path = "outputs/t05_clean_stops.csv"
    t05_expected_cols = ["stop_id", "stop_name", "stop_lat", "stop_lon"]
    results.append(validate_file_exists(t05_path, "t05_clean_stops"))
    results.append(validate_csv_columns(t05_path, t05_expected_cols, "t05_clean_stops"))
    results.append(validate_csv_row_count(t05_path, "t05_clean_stops", min_rows=1))
    results.append(validate_numeric_columns(
        t05_path, [2, 3], "t05_clean_stops"
    ))
    results.append(validate_value_range(
        t05_path, 2, -90, 90, "t05_clean_stops"
    ))
    results.append(validate_value_range(
        t05_path, 3, -180, 180, "t05_clean_stops"
    ))

    # --- t08_pois_clean.csv ---
    t08_path = "outputs/t08_pois_clean.csv"
    t08_expected_cols = [
        "qid", "label", "poi_type", "latitude", "longitude", "source",
    ]
    results.append(validate_file_exists(t08_path, "t08_pois_clean"))
    results.append(validate_csv_columns(t08_path, t08_expected_cols, "t08_pois_clean"))
    results.append(validate_csv_row_count(t08_path, "t08_pois_clean", min_rows=1))
    results.append(validate_no_empty_required_cols(
        t08_path, [0, 2, 5], "t08_pois_clean"
    ))
    results.append(validate_numeric_columns(
        t08_path, [3, 4], "t08_pois_clean"
    ))

    # --- t10_accessibility_scores.csv ---
    t10_path = "outputs/t10_accessibility_scores.csv"
    t10_expected_cols = [
        "qid", "label", "poi_type", "distance_m",
        "n_departures", "n_routes", "accessibility_score",
    ]
    results.append(validate_file_exists(t10_path, "t10_accessibility_scores"))
    results.append(validate_csv_columns(t10_path, t10_expected_cols, "t10_accessibility_scores"))
    results.append(validate_csv_row_count(t10_path, "t10_accessibility_scores", min_rows=1))
    results.append(validate_numeric_columns(
        t10_path, [3, 4, 5, 6], "t10_accessibility_scores"
    ))
    results.append(validate_value_range(
        t10_path, 6, 0.0, 1.0, "t10_accessibility_scores"
    ))

    # --- t13_city_clusters.csv ---
    t13_path = "outputs/t13_city_clusters.csv"
    t13_expected_cols = ["city_id", "city_name", "year", "cluster_id"]
    results.append(validate_file_exists(t13_path, "t13_city_clusters"))
    results.append(validate_csv_columns(t13_path, t13_expected_cols, "t13_city_clusters"))
    results.append(validate_csv_row_count(t13_path, "t13_city_clusters", min_rows=1))
    results.append(validate_no_empty_required_cols(
        t13_path, [0, 1, 2, 3], "t13_city_clusters"
    ))
    results.append(validate_numeric_columns(
        t13_path, [2, 3], "t13_city_clusters"
    ))

    return results


