    summary = []
    for passed, message in results:
        # Derive a check_name from the message (first token before the colon)
        check_name = message.split(":")[0].strip()
        summary.append({
            "check_name": check_name,
            "passed": passed,
            "message": message,
        })

    # Write output
    os.makedirs("outputs", exist_ok=True)
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, "w", encoding="utf-8") as fh:
        json.dump(summary, fh, indent=2, ensure_ascii=False)

    # Print summary to stdout
    passed_count = sum(1 for e in summary if e["passed"])
    total = len(summary)
    print(f"Validation complete: {passed_count}/{total} checks passed.")
    for entry in summary:
        status = "PASS" if entry["passed"] else "FAIL"
        print(f"  [{status}] {entry['message']}")

    # Exit with error code if any check failed
    if passed_count < total:
        sys.exit(1)


